1	import {
2	  type EventTimelineItem,
3	  MessageType_Tags,
4	  MsgLikeKind_Tags,
5	  OtherState_Tags,
6	  TimelineItemContent_Tags,
7	} from "@unomed/react-native-matrix-sdk";
8	
9	export const getLastMessageType = (
10	  event: EventTimelineItem | undefined,
11	): string => {
12	  const type = event?.content.tag;
13	  const senderName = event?.isOwn
14	    ? "You"
15	    : event?.senderProfile?.tag === "Ready"
16	      ? event?.senderProfile?.inner?.displayName || "Unknown"
17	      : "Unknown";
18	
19	  if (
20	    type === TimelineItemContent_Tags.CallInvite ||
21	    type === TimelineItemContent_Tags.RtcNotification
22	  ) {
23	    return `${senderName}: 🔔 Call notify`;
24	  }
25	
26	  if (type === TimelineItemContent_Tags.MsgLike) {
27	    const kind = event?.content.inner.content.kind;
28	    let messageBody = "";
29	
30	    if (kind?.tag === MsgLikeKind_Tags.Message) {
31	      const msgType = kind.inner.content.msgType;
32	
33	      if (msgType?.tag === MessageType_Tags.Text) {
34	        const rawBody = kind.inner.content.body || "";
35	        messageBody = rawBody.replace(
36	          /\[@?([^\]]+)\]\(https?:\/\/matrix\.to[^)]*\)/g,
37	          "@$1",
38	        );
39	      } else if (msgType?.tag === MessageType_Tags.Emote) {
40	        messageBody = kind.inner.content.body || "Emote";
41	      } else if (msgType?.tag === MessageType_Tags.Image) {
42	        messageBody = "📷 Image";
43	      } else if (msgType?.tag === MessageType_Tags.File) {
44	        messageBody = "📎 File";
45	      } else if (msgType?.tag === MessageType_Tags.Video) {
46	        messageBody = "🎥 Video";
47	      } else if (msgType?.tag === MessageType_Tags.Audio) {
48	        messageBody = "🎵 Audio";
49	      } else if (msgType?.tag === MessageType_Tags.Gallery) {
50	        messageBody = "🖼️ Gallery";
51	      } else if (msgType?.tag === MessageType_Tags.Notice) {
52	        messageBody = kind.inner.content.body || "Notice";
53	      } else if (msgType?.tag === MessageType_Tags.Location) {
54	        messageBody = "📍 Location";
55	      } else if (msgType?.tag === MessageType_Tags.Other) {
56	        messageBody = "Message";
57	      } else {
58	        messageBody = "Message";
59	      }
60	    }
61	
62	    if (kind?.tag === MsgLikeKind_Tags.Sticker) {
63	      messageBody = "🧩 Sticker";
64	    } else if (kind?.tag === MsgLikeKind_Tags.Poll) {
65	      messageBody = "📊 Poll";
66	    } else if (kind?.tag === MsgLikeKind_Tags.Redacted) {
67	      messageBody = "Message deleted";
68	    } else if (kind?.tag === MsgLikeKind_Tags.UnableToDecrypt) {
69	      messageBody = "Unable to decrypt message";
70	    } else if (kind?.tag === MsgLikeKind_Tags.Other) {
71	      messageBody = "Message";
72	    }
73	
74	    return `${senderName}: ${messageBody || "Message"}`;
75	  }
76	
77	  if (type === TimelineItemContent_Tags.RoomMembership) {
78	    return `${senderName}: Room name changed`;
79	  }
80	
81	  if (type === TimelineItemContent_Tags.ProfileChange) {
82	    return `${senderName}: Personal settings changed`;
83	  }
84	
85	  if (type === TimelineItemContent_Tags.State) {
86	    const stateContent = event?.content.inner.content;
87	    if (stateContent?.tag === OtherState_Tags.RoomName) {
88	      return `${senderName}: Room name changed`;
89	    }
90	    if (stateContent?.tag === OtherState_Tags.RoomTopic) {
91	      const topic = stateContent.inner.topic;
92	      return topic
93	        ? `${senderName}: Room topic changed to ${topic}`
94	        : `${senderName}: Room topic changed`;
95	    }
96	    if (stateContent?.tag === OtherState_Tags.RoomAvatar) {
97	      return `${senderName}: Room avatar changed`;
98	    }
99	    if (stateContent?.tag === OtherState_Tags.RoomEncryption) {
100	      return `${senderName}: Room encryption changed`;
101	    }
102	    if (stateContent?.tag === OtherState_Tags.RoomJoinRules) {
103	      return `${senderName}: Room join rules changed`;
104	    }
105	    if (stateContent?.tag === OtherState_Tags.RoomHistoryVisibility) {
106	      return `${senderName}: Room history visibility changed`;
107	    }
108	    if (stateContent?.tag === OtherState_Tags.PolicyRuleRoom) {
109	      return `${senderName}: Room policy rule changed`;
110	    }
111	    if (stateContent?.tag === OtherState_Tags.RoomPinnedEvents) {
112	      return `${senderName}: Room pinned events changed`;
113	    }
114	  }
115	
116	  if (
117	    type === TimelineItemContent_Tags.FailedToParseMessageLike ||
118	    type === TimelineItemContent_Tags.FailedToParseState
119	  ) {
120	    return `${senderName}: Unsupported message`;
121	  }
122	
123	  return "Unknown message type";
124	};
