3	export function getSortedRoomsByLastMessage(rooms: Room[]): Room[] {
4	  return rooms
5	    .filter((room) => room.getLiveTimeline().getEvents().length > 0)
6	    .sort((a, b) => {
7	      const aEvents = a.getLiveTimeline().getEvents();
8	      const bEvents = b.getLiveTimeline().getEvents();
9	
10	      const aLast = aEvents[aEvents.length - 1]?.getTs() || 0;
11	      const bLast = bEvents[bEvents.length - 1]?.getTs() || 0;
12	
13	      return bLast - aLast;
14	    });
15	}
